"use client";
import StudioPage from "./studio-page";

import BackContainer from "./backcontainer";
import { containerColors3 } from "./backcontainer";
// Background for the /video page (blue / cyan / teal)

function ModelPageBackground() {
    return <div style={{ position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 0 }}>
        <BackContainer colors={containerColors3} />

    </div>;
}


export default function ModelPage() {
    return <StudioPage mode="model" background={<ModelPageBackground />} />;
}
